# CP26 Step 7B reconstructed representative real-FCS NK gating atlas.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","figure_framework.R")); rp_install_and_load(c("dplyr","readr","tibble","ggplot2","patchwork","stringr"),"flowCore"); source(file.path(sd_repo_root(),"R","panels","CP26","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP26"); r<-file.path(a,"11_RData"); out<-file.path(a,"05_flow_figures_flowjo_style_TALL_LAYOUT_WHITE_BG"); dir.create(out,recursive=TRUE,showWarnings=FALSE); load(file.path(r,"SDY2583_CP26_STEP1_inventory_RECONSTRUCTED.RData")); load(file.path(r,"SDY2583_CP26_STEP4_composite_scores_RECONSTRUCTED.RData")); reps<-rp_select_representative_subjects(scored_data,CP26_MANIFEST$integrated_score); readr::write_csv(reps,file.path(out,"SDY2583_CP26_representative_samples_RECONSTRUCTED.csv")); plots<-list()
for(i in seq_len(nrow(reps))){sid<-reps$subject_id[i]; group<-as.character(reps$disease_group[i]); path<-fcs_files[grepl(paste0("^",sid,"_CP26"),basename(fcs_files))][1]; obj<-rp_read_transform(path); map<-obj$marker_map; ex<-flowCore::exprs(obj$ff); ch<-c(DUMP=rp_find_channel(map,c("Viability.*CD3.*CD13.*CD19.*CD123","dump"),"BV510-A"),CD45=rp_find_channel(map,c("^CD45$"),"BB515-A"),CD56=rp_find_channel(map,c("^CD56$"),"PE-CF594-A"),CD16=rp_find_channel(map,c("^CD16$"),"BV421-A"),NKG2D=rp_find_channel(map,c("NKG2D"),"PE-Cy7-A"),CD161=rp_find_channel(map,c("CD161"),"PE-A"),NKG2C=rp_find_channel(map,c("NKG2C"),"BV711-A"),CD57=rp_find_channel(map,c("^CD57$"),"BV786-A")); primary<-rp_vec(ex,ch["DUMP"])<=1.5 & rp_vec(ex,ch["CD45"])>2; nk<-primary & (rp_vec(ex,ch["CD56"])>1.5 | rp_vec(ex,ch["CD16"])>1.5)
plots[[length(plots)+1]]<-rp_flow_density_plot(ex,ch["CD45"],ch["DUMP"],2,1.5,paste(group,sid,"CD45/dump")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[primary,,drop=FALSE],ch["CD56"],ch["CD16"],1.5,1.5,paste(group,"CD56/CD16")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[nk,,drop=FALSE],ch["NKG2D"],ch["CD161"],1.5,1.5,paste(group,"NKG2D/CD161")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[nk,,drop=FALSE],ch["NKG2C"],ch["CD57"],1.5,1.5,paste(group,"NKG2C/CD57"))}
rp_save_flow_atlas(plots,file.path(out,"Figure_CP26_representative_NK_gating_RECONSTRUCTED.pdf"),ncol=2,width=9,height=16)
